public int Slack(int start, int end) {
    Break a = breaks[start], b = breaks[end];
    int length = offsets[b.ew] + b.ec - offsets[a.sw] - a.sc + (b.hyphen ? 1 : 0);
    return (start == 0 ? first : later) - length;
